import{b as i,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"安装与配置","description":"","frontmatter":{},"headers":[],"relativePath":"git/intro/setup/index.md","filePath":"Git操作手册/1.起步/02.安装与配置.md","lastUpdated":1781394803000}'),n={name:"git/intro/setup/index.md"};function l(h,s,p,k,d,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="安装与配置" tabindex="-1">安装与配置 <a class="header-anchor" href="#安装与配置" aria-label="Permalink to &quot;安装与配置&quot;">​</a></h1><blockquote><p>本地安装 -&gt; 首次配置 -&gt; SSH Key -&gt; 连接 GitHub</p></blockquote><h2 id="安装-git" tabindex="-1">安装 Git <a class="header-anchor" href="#安装-git" aria-label="Permalink to &quot;安装 Git&quot;">​</a></h2><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>推荐 Homebrew，一条命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><p>验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git version 2.xx.x</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>去 <a href="https://git-scm.com/downloads/win" target="_blank" rel="noreferrer">Git 官网下载页</a> 下载安装包，一路 Next 即可。安装完成后右键菜单会出现 &quot;Git Bash Here&quot;，这就是你的 Git 终端。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CentOS / RHEL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ubuntu / Debian</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><h2 id="首次配置" tabindex="-1">首次配置 <a class="header-anchor" href="#首次配置" aria-label="Permalink to &quot;首次配置&quot;">​</a></h2><p>装好 Git 之后，先告诉 Git 你是谁——每次提交都会带上这个信息：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的名字&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的邮箱@example.com&quot;</span></span></code></pre></div><p><code>--global</code> 表示全局生效，这台电脑上所有 Git 仓库都会用这个配置。如果某个项目想用不同的名字，去掉 <code>--global</code> 在该项目目录下执行即可。</p><h3 id="查看配置" tabindex="-1">查看配置 <a class="header-anchor" href="#查看配置" aria-label="Permalink to &quot;查看配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 查看所有配置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 查看用户名</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 查看邮箱</span></span></code></pre></div><h2 id="配置-ssh-key" tabindex="-1">配置 SSH Key <a class="header-anchor" href="#配置-ssh-key" aria-label="Permalink to &quot;配置 SSH Key&quot;">​</a></h2><p>Git 和 GitHub 之间通信需要身份验证。推荐用 SSH——配一次，以后不用输密码。</p><h3 id="_1-生成-ssh-key" tabindex="-1">1. 生成 SSH Key <a class="header-anchor" href="#_1-生成-ssh-key" aria-label="Permalink to &quot;1. 生成 SSH Key&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的邮箱@example.com&quot;</span></span></code></pre></div><p>一路回车即可。完成后在 <code>~/.ssh/</code> 目录下生成两个文件：</p><ul><li><code>id_rsa</code> — 私钥，<strong>谁都不能给</strong></li><li><code>id_rsa.pub</code> — 公钥，放到 GitHub 上</li></ul><h3 id="_2-复制公钥" tabindex="-1">2. 复制公钥 <a class="header-anchor" href="#_2-复制公钥" aria-label="Permalink to &quot;2. 复制公钥&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_rsa.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pbcopy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (Git Bash)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_rsa.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> clip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_rsa.pub</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 手动复制输出内容</span></span></code></pre></div><h3 id="_3-添加到-github" tabindex="-1">3. 添加到 GitHub <a class="header-anchor" href="#_3-添加到-github" aria-label="Permalink to &quot;3. 添加到 GitHub&quot;">​</a></h3><p>打开 GitHub → Settings → SSH and GPG keys → New SSH key，把公钥内容粘贴进去。</p><h3 id="_4-测试连接" tabindex="-1">4. 测试连接 <a class="header-anchor" href="#_4-测试连接" aria-label="Permalink to &quot;4. 测试连接&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre></div><p>看到 <code>Hi xxx! You&#39;ve successfully authenticated</code> 就说明通了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章做好了三件事：</p><ol><li><strong>Git 装好了</strong> — <code>git --version</code> 能看到版本号</li><li><strong>身份配置了</strong> — <code>user.name</code> 和 <code>user.email</code> 设好，提交时会带上</li><li><strong>SSH 打通了</strong> — Git 和 GitHub 之间不再需要输密码</li></ol><p>环境就绪，下一篇创建你的第一个 Git 仓库。</p><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>在你的电脑上安装 Git，确认 <code>git --version</code> 输出版本号</li><li>配置全局用户名和邮箱，用 <code>git config --list</code> 确认</li><li>生成 SSH Key 并添加到 GitHub，用 <code>ssh -T git@github.com</code> 测试</li></ol>`,37)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
